        this.addAnnotation((ENamedElement)this.getGraphic_Filename(), source, new String[]{"documentation", "Name of the file that should be displayed. This attribute is supported in ASAM FSX and kept in AUTOSAR in order to support cut and paste.\r\n\r\n\r\n"});
        this.addAnnotation((ENamedElement)this.getGraphic_Fit(), source, new String[]{"documentation", "It determines the way in which the graphic should be inserted.\r\n\r\nEnter the attribute value \"AS-IS\" , to insert a graphic in its original dimensions.\r\n\r\nThe graphic is adapted, if it is too big for the space for which it was intended. \r\nDefault is \"AS-IS\""});
        this.addAnnotation((ENamedElement)this.getGraphic_Generator(), source, new String[]{"documentation", "This attribute specifies the generator which is used to generate the image. \r\n\r\nUse case is that when editing a documentation, a figure (to be delivered by the  modeling tool) is inserted by the authoring tool as reference (this is the role  of graphic). But the real figure maybe injected during document processing. To  be able to recognize this situation, this attribute can be applied.\r\n"});
        this.addAnnotation((ENamedElement)this.getGraphic_Height(), source, new String[]{"documentation", "Define the displayed height of the figure."});
        this.addAnnotation((ENamedElement)this.getGraphic_HtmlFit(), source, new String[]{"documentation", "How to fit the graphic in an online media. Default is AS-IS."});
        this.addAnnotation((ENamedElement)this.getGraphic_HtmlHeight(), source, new String[]{"documentation", "Specifies the height of the graphic when it is displayed online."});
        this.addAnnotation((ENamedElement)this.getGraphic_HtmlScale(), source, new String[]{"documentation", "Set the proportional scale when displayed online."});
        this.addAnnotation((ENamedElement)this.getGraphic_HtmlWidth(), source, new String[]{"documentation", "Specifies the width of the graphic when it is displayed online."});
        this.addAnnotation((ENamedElement)this.getGraphic_Notation(), source, new String[]{"documentation", "This attribute captures the format used to represent the graphic."});
        this.addAnnotation((ENamedElement)this.getGraphic_Scale(), source, new String[]{"documentation", "In this element the dimensions of the graphic can be altered proportionally."});
        this.addAnnotation((ENamedElement)this.getGraphic_Width(), source, new String[]{"documentation", "Define the displayed width of the figure."});
        this.addAnnotation((ENamedElement)this.graphicFitEnumEEnum, source, new String[]{"documentation", "This enumerator specifies the policy how to place and scale the figure on the page.\r\n"});
        this.addAnnotation((ENamedElement)this.graphicFitEnumEEnum.getELiterals().get(0), source, new String[]{"documentation", "This indicates that the image shall be incorporated as is without scaling, rotation etc.\r\n"});
        this.addAnnotation((ENamedElement)this.graphicFitEnumEEnum.getELiterals().get(1), source, new String[]{"documentation", "Rotate 90 degree clockwise"});
        this.addAnnotation((ENamedElement)this.graphicFitEnumEEnum.getELiterals().get(2), source, new String[]{"documentation", "Rotate 90 degree counter clockwise"});
        this.addAnnotation((ENamedElement)this.graphicFitEnumEEnum.getELiterals().get(3), source, new String[]{"documentation", "Rotate 180 degree"});
        this.addAnnotation((ENamedElement)this.graphicFitEnumEEnum.getELiterals().get(4), source, new String[]{"documentation", "Rotate by 90 degree and then fit to text"});
        this.addAnnotation((ENamedElement)this.graphicFitEnumEEnum.getELiterals().get(5), source, new String[]{"documentation", "Rotate by 90 degree counter clock wise and then fit to text"});
        this.addAnnotation((ENamedElement)this.graphicFitEnumEEnum.getELiterals().get(6), source, new String[]{"documentation", "Rotate 180 degree"});
        this.addAnnotation((ENamedElement)this.graphicFitEnumEEnum.getELiterals().get(7), source, new String[]{"documentation", "Rotate by 90 degree and then fit to text"});
        this.addAnnotation((ENamedElement)this.graphicFitEnumEEnum.getELiterals().get(8), source, new String[]{"documentation", "Rotate by 90 degree counter clock wise and then fit to text"});
        this.addAnnotation((ENamedElement)this.graphicFitEnumEEnum.getELiterals().get(9), source, new String[]{"documentation", "fit to the text containing the graphic."});
        this.addAnnotation((ENamedElement)this.graphicFitEnumEEnum.getELiterals().get(10), source, new String[]{"documentation", "Fit to the page "});
        this.addAnnotation((ENamedElement)this.graphicFitEnumEEnum.getELiterals().get(11), source, new String[]{"documentation", "This indicates that the width of the graphic shall be limited to the width of the current '''text flow'''. The image shall not be scaled down but cropped.\r\n"});
        this.addAnnotation((ENamedElement)this.graphicFitEnumEEnum.getELiterals().get(12), source, new String[]{"documentation", "This indicates that the width of the graphic shall be limited to the '''page width'''. The image shall not be scaled down but cropped.\r\n"});
        this.addAnnotation((ENamedElement)this.graphicNotationEnumEEnum, source, new String[]{"documentation", "This enumerator specifies the various notations (finally file types) used to represent the figure.\r\n"});
        this.addAnnotation((ENamedElement)this.graphicNotationEnumEEnum.getELiterals().get(0), source, new String[]{"documentation", "Encapsulated Postscript"});
        this.addAnnotation((ENamedElement)this.graphicNotationEnumEEnum.getELiterals().get(1), source, new String[]{"documentation", "Graphics Interchange Format\r\n"});
        this.addAnnotation((ENamedElement)this.graphicNotationEnumEEnum.getELiterals().get(2), source, new String[]{"documentation", "scalable vector graphic"});
        this.addAnnotation((ENamedElement)this.graphicNotationEnumEEnum.getELiterals().get(3), source, new String[]{"documentation", "\"Joint Photographic Experts Group\"  format\r\n"});
        this.addAnnotation((ENamedElement)this.mapEClass, source, new String[]{"documentation", "Image maps enable authors to specify regions of an image or object and assign a specific action to each region (e.g., retrieve a document, run a program, etc.) When the region is activated by the user, the action is executed.\r\n\r\nThe class follows the html approach and is intended to support interactive documents.\r\n"});
        this.addAnnotation((ENamedElement)this.getMap_Class(), source, new String[]{"documentation", "This attribute assigns a class name or set of class names to an element. Any number of elements may be assigned the same class name or set of class names. Multiple class names must be separated by white space characters. Class names are typically used to apply CSS formatting rules to an element.\r\n"});
        this.addAnnotation((ENamedElement)this.getMap_Name(), source, new String[]{"documentation", "This attribute assigns a name to the image map in the MAP element. This name can be used to be referenced in an HTML image through the attribute USEMAP. Although this is not actually necessary in the\r\nMSR model, it was inserted in order to support the MAPs which were created for HTML.\r\n"});
        this.addAnnotation((ENamedElement)this.getMap_Onclick(), source, new String[]{"documentation", "The ONCLICK-Event occurs, if the current element is clicked on. A script can be stored in\r\nthis attribute to be performed in the Event."});
        this.addAnnotation((ENamedElement)this.getMap_Ondblclick(), source, new String[]{"documentation", "The ONDBLCLICK-Event occurs, if the current Event is \"double\" clicked-on. \r\nA script can be stored in this attribute to be performed in the Event."});
        this.addAnnotation((ENamedElement)this.getMap_Onkeydown(), source, new String[]{"documentation", "The ONKEYDOWN-Event occurs, if a button on the current element is pressed down. \r\n\r\nA script can be stored in this attribute to be performed in the event."});
        this.addAnnotation((ENamedElement)this.getMap_Onkeypress(), source, new String[]{"documentation", "The ONKEYPRESS-Event occurs, if a button on the current element is pressed down and released. \r\n\r\nA script can be stored in this attribute to be performed in the Event."});
        this.addAnnotation((ENamedElement)this.getMap_Onkeyup(), source, new String[]{"documentation", "The ONKEYUP-Event occurs, if a button on the current element is released. \r\n\r\nA script can be stored in this attribute to be performed in the Event."});
        this.addAnnotation((ENamedElement)this.getMap_Onmousedown(), source, new String[]{"documentation", "The ONMOUSEDOWN-Event occurs, if the mouse button used for clicking is held down on the current element. \r\n\r\nA script can be stored in this attribute to be performed in the Event."});
        this.addAnnotation((ENamedElement)this.getMap_Onmousemove(), source, new String[]{"documentation", "The ONMOUSEMOVE-Event occurs, if the mouse pointer is moved on the current \r\nelement (i.e. it is located on the current element). \r\n\r\nA script can be stored in this attribute to be performed in the Event."});
        this.addAnnotation((ENamedElement)this.getMap_Onmouseout(), source, new String[]{"documentation", "The ONMOUSEOUT-Event occurs, if the mouse pointer is moved from the current element.\r\n\r\nA script can be stored in this attribute to be performed in the Event."});
        this.addAnnotation((ENamedElement)this.getMap_Onmouseover(), source, new String[]{"documentation", "The ONMOUSEOVER-Event occurs, if the mouse pointer is moved to the current element\r\nfrom another location outside it. \r\n\r\nA script can be stored in this attribute to be performed in the Event."});
        this.addAnnotation((ENamedElement)this.getMap_Onmouseup(), source, new String[]{"documentation", "The ONMOUSEUP-Event occurs if the mouse button used for clicking is released on the\r\ncurrent element. \r\n\r\nA script can be stored in this attribute to be performed in the Event."});
        this.addAnnotation((ENamedElement)this.getMap_Style(), source, new String[]{"documentation", "This attribute specifies formatting style information for the current element. The content of this attribute is called inline CSS. The style attribute is deprecated (considered outdated), because it fuses together content and formatting.\r\n"});
        this.addAnnotation((ENamedElement)this.getMap_Title(), source, new String[]{"documentation", "This attribute offers advisory information. Some Web browsers will display this information as tooltips. Authoring tools may make this information available to users as additional information about the element."});
        this.addAnnotation((ENamedElement)this.getMap_Areas(), source, new String[]{"documentation", "This element specifies a region in an image map. Image maps enable authors to specify regions in an object (e.g. a graphic) and to assign a specific activity to each region (e.g. load a document, launch a program etc.)."});
        this.addAnnotation((ENamedElement)this.areaEClass, source, new String[]{"documentation", "This element specifies a region in an image map. Image maps enable authors to specify regions in an object (e.g. a graphic) and to assign a specific activity to each region (e.g. load a document, launch a program etc.).\r\n\r\nFor more details refer to the specification of HTML."});
        this.addAnnotation((ENamedElement)this.getArea_Accesskey(), source, new String[]{"documentation", "This attribute assigns an access key to an element.\r\nAn access key is an individual character (e.g. \"B\") within the document character\r\nrange. If an access key with an element assigned to it is pressed, the element comes\r\ninto focus. The activity performed when an element comes into focus, is dependent on\r\nthe element itself"});
        this.addAnnotation((ENamedElement)this.getArea_Alt(), source, new String[]{"documentation", "This attribute specifies the text to be inserted as an alternative to illustrations, shapes or applets, where these\r\ncannot be displayed by user agents."});
        this.addAnnotation((ENamedElement)this.getArea_Class(), source, new String[]{"documentation", "Blank separated list of classes"});
        this.addAnnotation((ENamedElement)this.getArea_Coords(), source, new String[]{"documentation", "This attribute specifies the position and shape on the screen.\r\nThe number of values and their order depend on the geometrical figure defined. "});
        this.addAnnotation((ENamedElement)this.getArea_Href(), source, new String[]{"documentation", "This attribute specifies the memory location of a web resource. It is therefore able to specify a link between the current element and the target element."});
        this.addAnnotation((ENamedElement)this.getArea_Nohref(), source, new String[]{"documentation", "If this attribute is set, the Area has no associated link.\r\n"});
        this.addAnnotation((ENamedElement)this.getArea_Onblur(), source, new String[]{"documentation", "The ONBLUR-Event occurs, when focus is switched away from an element. \r\n\r\nA script can be stored in this attribute to be performed in the Event."});
