        this.addAnnotation((ENamedElement)this.getArea_Onkeydown(), source, new String[]{"documentation", "The ONKEYDOWN-Event occurs, if a button on the current element is pressed down. \r\n\r\nA script can be stored in this attribute to be performed in the event."});
