        this.addAnnotation((ENamedElement)this.getArea_Tabindex(), source, new String[]{"documentation", "This attribute specifies the position of the current element in tabbing-order for the corresponding document.\r\n\r\nThe value must lie between 0 and 32767. The Tabbing Order defines the sequence in which elements are focused on, when the user navigates using the keyboard."});
